$uri_path = parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH);
$uri_segments = explode('/', $uri_path);
$curr_post_slug = $uri_segments[array_key_last($uri_segments) - 1];

$category = get_the_category();
if (!empty($category)) {
	$curr_cat_slug = $category[0]->slug;
	$parent_slug = get_category($category[0]->category_parent);
	$curr_parent_slug = $parent_slug ? $parent_slug->slug : null;
}

// $categories_args = [
// 	'parent' => 0,
// 	'number' => 0,
// 	'exclude' => 1,
// 	'hide_empty' => 0,
// ];
// $categories_posts = get_categories($categories_args);

$categories_args = [
    'taxonomy'   => 'category',         // Specify taxonomy
    'parent'     => 0,
    'number'     => 0,
    'exclude'    => 1,
    'hide_empty' => 0,
    'orderby'    => 'meta_value',       // Order by custom field
    'meta_key'   => 'order', // Replace with your custom field key
    'order'      => 'ASC'               // Change to 'DESC' for descending order
];

$categories_posts = get_terms($categories_args);

$p_categories = wp_get_post_categories(get_the_ID());

?>

<div class="col-md-3">
	<?php if (!empty($categories_posts)): ?>
	<?php foreach ($categories_posts as $i => $category):

	?>
	<?php if (!category_has_parent($category->term_id)): ?>
	<?php
	$is_open = in_array($category->term_id, $p_categories);
	$bar_status = $is_open ? 'show' : '';
	$aria_status = $is_open ? 'true' : 'false';
	?>
	<button class="sidebar-title-postHeading" type="button" data-bs-toggle="collapse" data-bs-target="#multiCollapseExample<?php echo $category->term_id; ?>" aria-expanded="<?php echo $aria_status ? 'true' : 'false'; ?>" aria-controls="multiCollapseExample<?php echo $category->term_id; ?>">
		<?php echo $category->name; ?>
		<span class="<?php echo $aria_status ? 'sidebar-icon-open' : 'sidebar-icon-close'; ?>">
			<i class="<?php echo $aria_status ? 'fa fa-angle-up' : 'fa fa-angle-down'; ?>"></i>
		</span>
	</button>
	<div class="BorderBottom"></div>
	<div class="policySectionHeight scrollbar multi-collapse collapse <?php echo $bar_status; ?>" id="multiCollapseExample<?php echo $category->term_id; ?>">
		<div class="sidebar-menu-post">
			<div class="menu-home-page-menu-container">
				<div class="panel-group" id="accordion">
					<div class="panel-default">
						<?php
						// Display posts of the parent category
						

						// Display subcategories and their posts
						display_categories($category->term_id, $curr_post_slug);
						display_category_posts($category->term_id, $curr_post_slug);
						?>
					</div>
				</div>
			</div>
		</div>
	</div>
	<?php endif; ?>
	<?php endforeach; ?>
	<?php endif; ?>
</div><!-- #secondary -->